 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    for color in range(10):
        if color == bg:
            continue
        # Prefix sums let us test all plausible rectangular objects, even when
        # stray pixels split their same-color components.
        ps = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                ps[r+1][c+1] = (ps[r][c+1] + ps[r+1][c] - ps[r][c]
                                + (grid[r][c] == color))
        candidates = []
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        area = (r1-r0+1) * (c1-c0+1)
                        n = (ps[r1+1][c1+1] - ps[r0][c1+1]
                             - ps[r1+1][c0] + ps[r0][c0])
                        if n >= 3 and n * 4 >= area * 3:
                            candidates.append((r0, r1, c0, c1, n, area))
        # Keep maximal supported rectangles: smaller sub-rectangles are merely
        # portions of the same object, while isolated speckles are discarded.
        candidates.sort(key=lambda x: (x[5], x[4]), reverse=True)
        kept = []
        for cand in candidates:
            r0, r1, c0, c1 = cand[:4]
            if any(a <= r0 and b >= r1 and c <= c0 and d >= c1
                   for a, b, c, d, _, _ in kept):
                continue
            kept.append(cand)
        for r0, r1, c0, c1, _, _ in kept:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color
    return out
